def transform(grid):
    g=[row[:] for row in grid]
    R,C=len(g),len(g[0]); frames=[]
    for color in range(1,10):
        pts=[(r,c) for r in range(R) for c in range(C) if g[r][c]==color]
        if not pts: continue
        r0=min(r for r,c in pts); r1=max(r for r,c in pts); c0=min(c for r,c in pts); c1=max(c for r,c in pts)
        if all(g[r0][c]==color and g[r1][c]==color for c in range(c0,c1+1)) and all(g[r][c0]==color and g[r][c1]==color for r in range(r0,r1+1)):
            pat=[[g[r][c] for c in range(c0+1,c1)] for r in range(r0+1,r1)]
            frames.append((color,r0,r1,c0,c1,pat))
    for src in frames:
        col0,a,b,c,d,pat=src
        if not any(x for row in pat for x in row): continue
        for col,r0,r1,c0,c1,inside in frames:
            if (col,r0,r1,c0,c1)==(col0,a,b,c,d) or (r1-r0,c1-c0)!=(b-a,d-c): continue
            if any(x for row in inside for x in row): continue
            for i in range(len(pat)):
                for j in range(len(pat[0])):
                    if pat[i][j]: g[r0+1+i][c0+1+j]=col
    return g

